talScrollbar = true; lstHistory.IntegralHeight = false; lstHistory.DrawMode = DrawMode.OwnerDrawFixed; lstHistory.ItemHeight = 34; lstHistory.DrawItem -= LstHistory_DrawItem; lstHistory.DrawItem += LstHistory_DrawItem; btnClear.Text = "CLEAR ALL HISTORY"; btnClear.Font = new Font("Segoe UI", 8.5F, FontStyle.Bold); btnClear.ForeColor = Color.White; btnClear.BackColor = dangerColor; btnClear.FlatStyle = FlatStyle.Flat; btnClear.FlatAppearance.BorderColor = Color.FromArgb(225, 80, 92); btnClear.FlatAppearance.BorderSize = 1; btnClear.Cursor = Cursors.Hand; btnBack.Text = "RETURN"; btnBack.Font = new Font("Segoe UI", 8.5F, FontStyle.Bold); btnBack.ForeColor = textColor; btnBack.BackColor = Color.FromArgb(25, 32, 44); btnBack.FlatStyle = FlatStyle.Flat; btnBack.FlatAppearance.BorderColor = Color.FromArgb(60, 73, 94); btnBack.FlatAppearance.BorderSize = 1; btnBack.Cursor = Cursors.Hand; btnClear.MouseEnter -= BtnClear_MouseEnter; btnClear.MouseLeave -= BtnClear_MouseLeave; btnClear.MouseDown -= BtnClear_MouseDown; btnClear.MouseUp -= BtnClear_MouseUp; btnBack.MouseEnter -= BtnBack_MouseEnter; btnBack.MouseLeave -= BtnBack_MouseLeave; btnBack.MouseDown -= BtnBack_MouseDown; btnBack.MouseUp -= BtnBack_MouseUp; btnClear.MouseEnter += BtnClear_MouseEnter; btnClear.MouseLeave += BtnClear_MouseLeave; btnClear.MouseDown += BtnClear_MouseDown; btnClear.MouseUp += BtnClear_MouseUp; btnBack.MouseEnter += BtnBack_MouseEnter; btnBack.MouseLeave += BtnBack_MouseLeave; btnBack.MouseDown += BtnBack_MouseDown; btnBack.MouseUp += BtnBack_MouseUp; footer = new Label(); footer.Text = "DEVELOPED BY SYED HUSSAIN ABBAS"; footer.Font = new Font("Consolas", 8F, FontStyle.Bold); footer.ForeColor = Color.FromArgb(82, 96, 116); footer.BackColor = backgroundColor; footer.TextAlign = ContentAlignment.MiddleCenter; Controls.Add(footer); Label topLine = new Label(); topLine.Name = "lblTopLine"; topLine.Text = "ARCHIVE CONTROL // SECURE RECORD STORAGE"; topLine.Font = new Font("Consolas", 8F, FontStyle.Bold); topLine.ForeColor = Color.FromArgb(80, 100, 125); topLine.BackColor = Color.Transparent; topLine.TextAlign = ContentAlignment.MiddleRight; Controls.Add(topLine); Label windowClose = CreateWindowButton("×"); windowClose.Name = "windowClose"; windowClose.Click += (s, e) => Close(); Controls.Add(windowClose); Label windowMax = CreateWindowButton("□"); windowMax.Name = "windowMax"; windowMax.Click += (s, e) => { WindowState = WindowState == FormWindowState.Maximized ? FormWindowState.Normal : FormWindowState.Maximized; }; Controls.Add(windowMax); Label windowMin = CreateWindowButton("—"); windowMin.Name = "windowMin"; windowMin.Click += (s, e) => { WindowState = FormWindowState.Minimized; }; Controls.Add(windowMin); UpdateLayout(); } private Label CreateWindowButton(string text) { Label label = new Label(); label.Text = text; label.Font = new Font("Segoe UI", 11F, FontStyle.Regular); label.ForeColor = Color.FromArgb(135, 150, 170); label.BackColor = Color.Transparent; label.TextAlign = ContentAlignment.MiddleCenter; label.Cursor = Cursors.Hand; label.MouseEnter += (s, e) => { label.ForeColor = Color.White; }; label.MouseLeave += (s, e) => { label.ForeColor = Color.FromArgb(135, 150, 170); }; return label; } private void UpdateLayout() { if (ClientSize.Width <= 1 || ClientSize.Height <= 1) return; int width = ClientSize.Width; int height = ClientSize.Height; Label topLine = Controls.Find("lblTopLine", false).FirstOrDefault() as Label; Label windowClose = Controls.Find("windowClose", false).FirstOrDefault() as Label; Label windowMax = Controls.Find("windowMax", false).FirstOrDefault() as Label; Label windowMin = Controls.Find("windowMin", false).FirstOrDefault() as Label; lblEdition.SetBounds(42, 20, 260, 22); lblTitle.SetBounds(42, 43, Math.Max(500, width - 520), 48); lblSubtitle.SetBounds(44, 91, 600, 24); if (topLine != null) { topLine.SetBounds(width - 520, 21, 410, 22); } if (windowMin != null) { windowMin.SetBounds(width - 135, 14, 40, 30); } if (windowMax != null) { windowMax.SetBounds(width - 95, 14, 40, 30); } if (windowClose != null) { windowClose.SetBounds(width - 55, 14, 40, 30); } lblStatus.SetBounds(width - 275, 74, 210, 25); int panelLeft = 35; int panelTop = 128; int panelWidth = width - 70; int panelHeight = height - 235; if (panelHeight < 350) panelHeight = 350; lblSection.SetBounds(panelLeft + 18, panelTop + 14, 220, 22); lblNormalCount.SetBounds(width - 410, panelTop + 14, 160, 22); lblTournamentCount.SetBounds(width - 235, panelTop + 14, 200, 22); lstHistory.SetBounds(panelLeft + 12, panelTop + 47, panelWidth - 24, panelHeight - 62); int buttonY = panelTop + panelHeight + 18; btnClear.SetBounds(width / 2 - 205, buttonY, 195, 42); btnBack.SetBounds(width / 2 + 10, buttonY, 150, 42); footer.SetBounds(250, height - 32, width - 500, 20); Invalidate(); } private void HistoryForm_Resize(object sender, EventArgs e) { UpdateLayout(); } private void HistoryForm_Paint(object sender, PaintEventArgs e) { if (ClientSize.Width <= 1 || ClientSize.Height <= 1) return; Graphics g = e.Graphics; g.SmoothingMode = SmoothingMode.AntiAlias; using (LinearGradientBrush brush = new LinearGradientBrush(ClientRectangle, backgroundColor, backgroundSecondary, 45F)) { g.FillRectangle(brush, ClientRectangle); } int offset = (int)(animationOffset % 42); using (Pen gridPen = new Pen(Color.FromArgb(10, 65, 90, 120), 1)) { for (int x = 0; x < ClientSize.Width; x += 42) { g.DrawLine(gridPen, x, 115 + offset, x, ClientSize.Height); } for (int y = 115; y < ClientSize.Height; y += 42) { g.DrawLine(gridPen, 0, y + offset, ClientSize.Width, y + offset); } } int glowAlpha = 18 + pulseValue / 3; using (SolidBrush glow = new SolidBrush(Color.FromArgb(glowAlpha, accentColor.R, accentColor.G, accentColor.B))) { g.FillEllipse(glow, ClientSize.Width / 2 - 370, -220, 740, 390); } using (Pen topLine = new Pen(Color.FromArgb(75 + pulseValue, accentColor.R, accentColor.G, accentColor.B), 1.5F)) { g.DrawLine(topLine, 42, 117, ClientSize.Width - 42, 117); } int panelLeft = 35; int panelTop = 128; int panelWidth = ClientSize.Width - 70; int panelHeight = ClientSize.Height - 235; if (panelHeight < 350) panelHeight = 350; using (SolidBrush panelBrush = new SolidBrush(Color.FromArgb(235, panelColor.R, panelColor.G, panelColor.B))) { g.FillRectangle(panelBrush, panelLeft, panelTop, panelWidth, panelHeight); } using (Pen panelPen = new Pen(borderColor, 1)) { g.DrawRectangle(panelPen, panelLeft, panelTop, panelWidth - 1, panelHeight - 1); } using (Pen sectionLine = new Pen(Color.FromArgb(45, 65, 155, 255), 1)) { g.DrawLine(sectionLine, panelLeft + 12, panelTop + 43, ClientSize.Width - panelLeft - 12, panelTop + 43); } using (Pen bottomLine = new Pen(Color.FromArgb(55, 65, 155, 255), 1)) { g.DrawLine(bottomLine, 42, ClientSize.Height - 67, ClientSize.Width - 42, ClientSize.Height - 67); } } private void LstHistory_DrawItem(object sender, DrawItemEventArgs e) { if (e.Index < 0 || e.Index >= lstHistory.Items.Count) return; string text = lstHistory.Items[e.Index]?.ToString() ?? ""; e.Graphics.SmoothingMode = SmoothingMode.AntiAlias; e.DrawBackground(); Rectangle rect = new Rectangle(e.Bounds.X + 8, e.Bounds.Y + 2, e.Bounds.Width - 16, e.Bounds.Height - 4); bool isNormalHeader = text.Contains("NORMAL MATCH HISTORY"); bool isTournamentHeader = text.Contains("TOURNAMENT HISTORY"); bool isEmpty = string.IsNullOrWhiteSpace(text); Color rowColor = e.Index % 2 == 0 ? Color.FromArgb(18, 25, 36) : Color.FromArgb(15, 21, 31); if (isNormalHeader) rowColor = Color.FromArgb(20, 47, 73); if (isTournamentHeader) rowColor = Color.FromArgb(48, 40, 23); if (isEmpty) { using (SolidBrush emptyBrush = new SolidBrush(listColor)) { e.Graphics.FillRectangle(emptyBrush, e.Bounds); } return; } using (SolidBrush rowBrush = new SolidBrush(rowColor)) { e.Graphics.FillRectangle(rowBrush, rect); } if (isNormalHeader || isTournamentHeader) { using (Pen line = new Pen(isNormalHeader ? accentColor : goldColor, 2)) { e.Graphics.DrawLine(line, rect.X, rect.Y, rect.X, rect.Bottom); } } Color textColorToUse = isNormalHeader ? accentBright : isTournamentHeader ? goldColor : Color.FromArgb(215, 223, 236); Font font = isNormalHeader || isTournamentHeader ? new Font("Consolas", 9F, FontStyle.Bold) : new Font("Consolas", 9F, FontStyle.Regular); using (SolidBrush textBrush = new SolidBrush(textColorToUse)) { e.Graphics.DrawString(text, font, textBrush, rect.X + 14, rect.Y + 8); } if (!isNormalHeader && !isTournamentHeader) { using (Pen separator = new Pen(Color.FromArgb(25, 55, 70, 90), 1)) { e.Graphics.DrawLine(separator, rect.X + 14, rect.Bottom - 1, rect.Right - 14, rect.Bottom - 1); } } if ((e.State & DrawItemState.Selected) == DrawItemState.Selected) { using (Pen selectedPen = new Pen(Color.FromArgb(80, accentColor.R, accentColor.G, accentColor.B), 1)) { e.Graphics.DrawRectangle(selectedPen, rect); } } font.Dispose(); } private void AnimationTimer_Tick(object sender, EventArgs e) { animationOffset += 0.28F; if (animationOffset >= 42) animationOffset = 0; if (pulseIncreasing) { pulseValue++; if (pulseValue >= 35) pulseIncreasing = false; } else { pulseValue--; if (pulseValue <= 0) pulseIncreasing = true; } if (lblStatus != null) { lblStatus.ForeColor = Color.FromArgb(175 + pulseValue, 215, 135); } if (IsHandleCreated) { Invalidate(new Rectangle(0, 0, ClientSize.Width, Math.Min(125, ClientSize.Height))); } } private void LoadHistoryData() { lstHistory.Items.Clear(); List<string> normalHistory = FileManager.LoadHistory(); List<string> tournamentHistory = FileManager.LoadTournamentHistory(); int normalCount = normalHistory.Count(x => !string.IsNullOrWhiteSpace(x)); int tournamentCount = tournamentHistory.Count(x => !string.IsNullOrWhiteSpace(x)); lblNormalCount.Text = "NORMAL // " + normalCount.ToString("00"); lblTournamentCount.Text = "TOURNAMENT // " + tournamentCount.ToString("00"); lstHistory.Items.Add("===== NORMAL MATCH HISTORY ====="); if (normalCount == 0) { lstHistory.Items.Add("NO NORMAL MATCH RECORDS AVAILABLE."); } else { foreach (string match in normalHistory) { if (!string.IsNullOrWhiteSpace(match)) lstHistory.Items.Add(match); } } lstHistory.Items.Add(""); lstHistory.Items.Add("===== TOURNAMENT HISTORY ====="); if (tournamentCount == 0) { lstHistory.Items.Add("NO TOURNAMENT RECORDS AVAILABLE."); } else { foreach (string match in tournamentHistory) { if (!string.IsNullOrWhiteSpace(match)) lstHistory.Items.Add(match); } } lblStatus.Text = normalCount + tournamentCount > 0 ? "● DATABASE ONLINE" : "● DATABASE EMPTY"; lblStatus.ForeColor = normalCount + tournamentCount > 0 ? successColor : mutedColor; lstHistory.Invalidate(); } private void btnClear_Click(object sender, EventArgs e) { DialogResult result = MessageBox.Show("This will permanently remove all normal match history and tournament records.\n\nDo you want to continue?", "CLEAR ARCHIVE", MessageBoxButtons.YesNo, MessageBoxIcon.Warning); if (result != DialogResult.Yes) return; FileManager.SaveHistory(new List<string>()); FileManager.ClearTournamentHistory(); LoadHistoryData(); MessageBox.Show("All match history has been cleared successfully.", "ARCHIVE CLEARED", MessageBoxButtons.OK, MessageBoxIcon.Information); } private void btnBack_Click(object sender, EventArgs e) { if (returnForm != null) { returnForm.Show(); returnForm.BringToFront(); Close(); return; } MainMenuForm menu = new MainMenuForm(); menu.Show(); Close(); } private void BtnClear_MouseEnter(object sender, EventArgs e) { btnClear.BackColor = Color.FromArgb(215, 65, 78); } private void BtnClear_MouseLeave(object sender, EventArgs e) { btnClear.BackColor = dangerColor; } private void BtnClear_MouseDown(object sender, MouseEventArgs e) { btnClear.BackColor = Color.FromArgb(145, 40, 52); } private void BtnClear_MouseUp(object sender, MouseEventArgs e) { btnClear.BackColor = Color.FromArgb(215, 65, 78); } private void BtnBack_MouseEnter(object sender, EventArgs e) { btnBack.BackColor = Color.FromArgb(38, 49, 66); } private void BtnBack_MouseLeave(object sender, EventArgs e) { btnBack.BackColor = Color.FromArgb(25, 32, 44); } private void BtnBack_MouseDown(object sender, MouseEventArgs e) { btnBack.BackColor = Color.FromArgb(18, 24, 34); } private void BtnBack_MouseUp(object sender, MouseEventArgs e) { btnBack.BackColor = Color.FromArgb(38, 49, 66); } private void HistoryForm_Load(object sender, EventArgs e) { LoadHistoryData(); } private void lstHistory_SelectedIndexChanged(object sender, EventArgs e) { } protected override void OnFormClosed(FormClosedEventArgs e) { if (animationTimer != null) { animationTimer.Stop(); animationTimer.Dispose(); } base.OnFormClosed(e); } } }